solution.Solution.cs:
using System.Globalization;

public interface IDiscount
{
    string Name { get; }
    decimal Apply(decimal total);
}

static class Amount
{
    public static decimal Cents(decimal x) => Math.Round(x, 2, MidpointRounding.AwayFromZero);
    public static string Text(decimal x) => x.ToString("0.##", CultureInfo.InvariantCulture);
}

public class PercentOff(decimal percent) : IDiscount
{
    public string Name => $"{Amount.Text(percent)}% off";
    public decimal Apply(decimal total) => Math.Max(0, Amount.Cents(total * (1 - percent / 100)));
}

public class AmountOff(decimal amount, decimal minimum) : IDiscount
{
    public string Name => $"{Amount.Text(amount)} off over {Amount.Text(minimum)}";
    public decimal Apply(decimal total) => total >= minimum ? Math.Max(0, Amount.Cents(total - amount)) : total;
}

public class FreeItem(decimal itemPrice) : IDiscount
{
    public string Name => "free item";
    public decimal Apply(decimal total) => Math.Max(0, Amount.Cents(total - itemPrice));
}

public static class Checkout
{
    public static (string Name, decimal Total) Best(decimal total, IEnumerable<IDiscount> discounts)
    {
        (string Name, decimal Total) best = ("none", total);
        foreach (var d in discounts)
        {
            decimal after = d.Apply(total);
            if (after < best.Total) best = (d.Name, after);
        }
        return best;
    }
}

public record Order(string Id, int Priority, DateTime Placed) : IComparable<Order>
{
    public int CompareTo(Order? other)
    {
        if (other is null) return 1;
        int c = Priority.CompareTo(other.Priority);
        if (c != 0) return c;
        c = Placed.CompareTo(other.Placed);
        return c != 0 ? c : string.CompareOrdinal(Id, other.Id);
    }
}

unitTests:
Test("each discount", () =>
{
    IDiscount p = new PercentOff(10);
    CheckEq(p.Name, "10% off");
    CheckEq(p.Apply(59.99m), 53.99m);
    IDiscount a = new AmountOff(5, 50);
    CheckEq(a.Name, "5 off over 50");
    CheckEq(a.Apply(49.99m), 49.99m);
    CheckEq(a.Apply(50m), 45m);
    CheckEq(new AmountOff(2.5m, 0).Name, "2.5 off over 0");
    CheckEq(new FreeItem(8m).Apply(5m), 0m);
    CheckEq(new PercentOff(12.5m).Name, "12.5% off");
});

Test("choosing the best discount", () =>
{
    IDiscount[] offers = [new PercentOff(10), new AmountOff(8, 60), new FreeItem(4.5m)];
    CheckEq(Checkout.Best(40m, offers), ("free item", 35.5m));
    CheckEq(Checkout.Best(100m, offers), ("10% off", 90m));
    CheckEq(Checkout.Best(80m, offers), ("10% off", 72m));
    CheckEq(Checkout.Best(70m, offers), ("8 off over 60", 62m));
    CheckEq(Checkout.Best(10m, []), ("none", 10m));
    CheckEq(Checkout.Best(10m, [new PercentOff(0)]), ("none", 10m));
});

Test("sorting orders", () =>
{
    var t = new DateTime(2026, 1, 1, 9, 0, 0);
    var orders = new List<Order>
    {
        new("C", 2, t), new("A", 1, t.AddMinutes(5)), new("B", 1, t), new("D", 2, t), new("E", 3, t.AddDays(-1)),
    };
    orders.Sort();
    CheckEq(orders.Select(o => o.Id), new[] { "B", "A", "C", "D", "E" });
    Check(new Order("X", 1, t) is IComparable<Order>, "Order should implement IComparable<Order>");
});

